17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        if (ownerAlreadyExists(owner) || emailAlreadyExists(owner)) {
107	            return new ResponseEntity<>(HttpStatus.CONFLICT);
108	        }
109	        if (owner.getRegistrationDate() == null) {
110	            owner.setRegistrationDate(LocalDate.now());
111	        }
112	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
113	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
114	        this.clinicService.saveOwner(owner);
115	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
116	        headers.setLocation(UriComponentsBuilder.newInstance()
117	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
118	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
119	    }
120	
121	    /**
122	     * Builds the customer code for a newly created owner in the given city, formatted as
123	     * {@code <UPPERCASE_CITY>-<NNNN>} where {@code NNNN} is one more than the number of owners
124	     * already stored in that city, zero-padded to four digits (e.g. {@code LONDON-0007}). The
125	     * count of existing owners in the city ignores letter case.
126	     *
127	     * @param city the city of the owner being created
128	     * @return the assigned customer code
129	     */
130	    private String nextCustomerCode(String city) {
131	        long ownersInCity = this.clinicService.findAllOwners().stream()
132	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
133	            .count();
134	        return String.format("%s-%04d", city.toUpperCase(), ownersInCity + 1);
135	    }
136	
137	    /**
138	     * Determines whether an owner already exists using the same telephone number.
139	     * Comparison ignores letter case and surrounding or repeated whitespace.
140	     *
141	     * @param owner the candidate owner to check
142	     * @return {@code true} if any other owner with the same telephone is already stored
143	     */
144	    private boolean ownerAlreadyExists(Owner owner) {
145	        String telephone = normalize(owner.getTelephone());
146	        return this.clinicService.findAllOwners().stream()
147	            .anyMatch(existing -> Objects.equals(normalize(existing.getTelephone()), telephone));
148	    }
149	
150	    /**
151	     * Determines whether another owner already uses the same email address.
152	     * Owners without an email are ignored, so a missing email never conflicts.
153	     * Comparison ignores letter case and surrounding or repeated whitespace.
154	     *
155	     * @param owner the candidate owner to check
156	     * @return {@code true} if the candidate supplies an email already used by a stored owner
157	     */
158	    private boolean emailAlreadyExists(Owner owner) {
159	        String email = normalize(owner.getEmail());
160	        if (email == null || email.isEmpty()) {
161	            return false;
162	        }
163	        return this.clinicService.findAllOwners().stream()
164	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
165	    }
166	
167	    /**
168	     * Normalizes a value for duplicate detection so that comparisons ignore letter
169	     * case and surrounding or repeated whitespace. Leading and trailing whitespace is
170	     * trimmed, any run of internal whitespace is collapsed to a single space, and the
171	     * result is lower-cased. For example {@code "  john   smith "} and {@code "John Smith"}
172	     * both normalize to {@code "john smith"}.
173	     *
174	     * @param value the raw value, may be {@code null}
175	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
176	     */
177	    private static String normalize(String value) {
178	        if (value == null) {
179	            return null;
180	        }
181	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
187	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
188	        if (currentOwner == null) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        currentOwner.setAddress(ownerFieldsDto.getAddress());
192	        currentOwner.setCity(ownerFieldsDto.getCity());
193	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
194	        currentOwner.setLastName(ownerFieldsDto.getLastName());
195	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
196	        this.clinicService.saveOwner(currentOwner);
197	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
198	    }
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Transactional
202	    @Override
203	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
204	        Owner owner = this.clinicService.findOwnerById(ownerId);
205	        if (owner == null) {
206	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	        }
208	        this.clinicService.deleteOwner(owner);
209	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
210	    }
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
215	        Owner owner = this.clinicService.findOwnerById(ownerId);
216	        if (owner == null) {
217	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
218	        }
219	        HttpHeaders headers = new HttpHeaders();
220	        Pet pet = petMapper.toPet(petFieldsDto);
221	        owner.setId(ownerId);
222	        pet.setOwner(owner);
223	        pet.getType().setName(null);
224	        this.clinicService.savePet(pet);
225	        PetDto petDto = petMapper.toPetDto(pet);
226	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
227	            .buildAndExpand(pet.getId()).toUri());
228	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
229	    }
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
234	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
235	        if (currentOwner != null) {
236	            Pet currentPet = this.clinicService.findPetById(petId);
237	            if (currentPet != null) {
238	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
239	                currentPet.setName(petFieldsDto.getName());
240	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
241	                this.clinicService.savePet(currentPet);
242	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
243	            }
244	        }
245	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
246	    }
247	
248	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
